<?php if(!$items): ?><div class="panel empty"><h3>Something delicious is on its way.</h3><p>No live dishes match these filters. Try another category or check back soon.</p><a class="pill" href="<?=e(url())?>">Clear filters</a></div><?php else: ?><div class="restaurant-grid"><?php foreach($items as $item): $visibleUntil=live_until($item); ?><article class="food-card favourite-capable" data-expires="<?=e(str_replace(' ','T',$visibleUntil).'Z')?>"><a class="food-image image-link" href="<?=e(url('dish.php?id='.$item['id']))?>"><img loading="lazy" src="<?=e(image_url($item['photo_id']))?>" alt="<?=e($item['name'])?>"><span class="tag"><?=e($item['category_name'])?></span></a><?=favourite_button('food',(int)$item['id'],'index.php',$item['name'])?><div class="food-content"><div class="food-title-row"><div><h3><a href="<?=e(url('dish.php?id='.$item['id']))?>"><?=e($item['name'])?></a></h3><div class="subtitle"><?=e($item['business_name'])?></div></div></div><div class="price-row"><span class="price">Rs <?=number_format($item['price_paisa']/100,2)?></span><form method="post" action="<?=e(url('cart.php'))?>" data-cart-form><?=csrf()?><input type="hidden" name="action" value="add"><input type="hidden" name="id" value="<?=$item['id']?>"><button class="pill compact primary"><?=ui_icon('plus',16)?> Add</button></form></div><small class="expires-note">Available until <?=e(local_time($visibleUntil))?></small></div></article><?php endforeach ?></div><?php endif ?>
